package com.gymflex.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity @Table(name="members") public class Member { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String name; @NotBlank @Column(unique=true) private String phone; @Email private String email; @NotBlank private String address; @ManyToOne(optional=false) private Plan plan; public Member(){} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public Plan getPlan(){return plan;} public void setPlan(Plan v){plan=v;} }